import assert from "node:assert/strict";
import { AsyncLocalStorage } from "node:async_hooks";
const results = [];
for (const entry of ["index", "core", "workerd"]) {
  const api = await import(new URL(`./packages/safe-js/dist/${entry}.js`, `file://${process.cwd()}/`));
  assert.equal(typeof api.admitNativePromiseProperties, "function");
  const storage = new AsyncLocalStorage();
  const key = Symbol("kResourceStore");
  const input = storage.run({ secret: "do-not-export" }, () => Promise.resolve(key));
  Object.defineProperty(input, key, { value: key });
  api.admitNativePromiseProperties(input, [key]);
  storage.disable();
  Object.preventExtensions(input);
  const source = "const key = Object.getOwnPropertySymbols(input)[0]; return [Object.getOwnPropertySymbols(input).length, input[key] === key, await input === key, Object.isExtensible(input)]";
  const original = await api.run(source, { bindings: { input } });
  assert.equal(original.ok, true);
  assert.deepEqual(original.returnValue, [1, true, true, false]);
  const { dump, restore } = await import(new URL("./packages/safe-js/dist/index.js", `file://${process.cwd()}/`));
  const saved = await dump(original);
  assert.equal(saved.includes("do-not-export"), false);
  const replay = await api.run(source, { snapshot: restore(JSON.parse(saved), { source }) });
  assert.equal(replay.ok, true);
  assert.deepEqual(replay.returnValue, [1, true, true, false]);
  results.push({ entry, original: true, completedReplay: true, isolated: true });
}
console.log(JSON.stringify({ versions: process.versions, results }));
